    {
        Revision = revision;
        Total = total;
        Completed = completed;
        Incomplete = incomplete;
        Unavailable = unavailable;
        Hidden = hidden;
        GroupedChoiceCount = groupedChoiceCount;
        CompletionRatePercent = total == 0 ? 0 : completed * 100d / total;
        ByFirstCategory = AsReadOnly(byFirstCategory);
